findings.codeql_raw_query:
/**
 * @name Improper Output Neutralization for Logs
 * @description Writing unneutralized user-controlled data to logs can allow for log injection attacks.
 * @kind path-problem
 * @problem.severity error
 * @id py/log-injection
 * @tags security
 *       external/cwe/cwe-117
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module LogInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Use the standard Logging concept which represents the message node directly
    sink instanceof Logging
  }
}

module LogInjectionFlow = TaintTracking::Global<LogInjectionConfig>;
import LogInjectionFlow::PathGraph

from LogInjectionFlow::PathNode source, LogInjectionFlow::PathNode sink
where LogInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Log entry depends on $@.", source.getNode(), "user-provided value"
